"</style></head>\n"
"<body><div class=\"shell\"><aside class=\"sidebar\"><div class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\"></span><strong>XH Multiscreen</strong></div><p class=\"model\">通用监看屏<span>C6</span></p><nav aria-label=\"设备设置\"><p class=\"nav-label\">显示内容</p><a href=\"/standalone#preview\">屏幕预览</a><a href=\"/standalone#bambu\">打印机</a><a href=\"/standalone#clockSection\">桌面时钟</a><a href=\"/standalone#weatherSection\">天气</a><a href=\"/standalone#home\">Home Assistant</a><p class=\"nav-label\">设备</p><a href=\"/standalone#display\">屏幕与轮转</a><a href=\"/standalone#sleep\">自动休眠</a><a href=\"/standalone#pairing\">局域网连接</a><a href=\"/\" aria-current=\"page\">Wi-Fi 连接</a></nav><p class=\"sidebar-note\">网络信息保存在这台设备中。<br>无需一直连接电脑，卡片仍可独立运行。</p></aside>\n"
"<main class=\"workspace\"><header class=\"page-heading\"><div><p class=\"eyebrow\">XH MULTISCREEN · C6</p><h1>Wi-Fi 连接</h1><p>将 C6 连接到你的局域网，随后在多屏灵犀中扫描添加。</p></div><div class=\"header-controls\"><label class=\"language-control\"><span data-no-i18n>语言 / Language</span><select id=\"pageLanguage\" aria-label=\"语言 / Language\" aria-describedby=\"languageStatus\"><option value=\"0\" lang=\"zh-CN\">中文</option><option value=\"1\" lang=\"en\">English</option></select></label><label>网页外观<select id=\"appearance\"><option value=\"system\">跟随系统</option><option value=\"light\">浅色</option><option value=\"dark\">深色</option></select></label></div></header>\n"
"<div class=\"language-feedback\"><p id=\"languageStatus\" class=\"hint\" role=\"status\" aria-live=\"polite\">网页与小屏使用同一语言，切换后自动保存。</p><button id=\"languageRetry\" type=\"button\" hidden>重试同步</button></div>\n"
"<section class=\"card stats\" aria-label=\"连接信息\"><div class=\"stat\"><small>设备地址</small><strong id=\"deviceIP\">正在读取…</strong></div><div class=\"stat\"><small>固件</small><strong id=\"firmware\">—</strong></div><div class=\"stat\"><small>连接状态</small><strong id=\"connectionState\">正在检查</strong></div></section>\n"
"<section id=\"handoff\" class=\"card\" hidden><h2>Wi-Fi 已连接</h2><p>手机切回同一 Wi-Fi，扫描小屏上的新二维码进入后台。</p><p id=\"lanAddress\" data-no-i18n></p><a id=\"continueSetup\" href=\"/standalone#preview\">继续配置设备</a></section>\n"
"<section class=\"card\"><div class=\"card-heading\"><h2>选择网络</h2><button id=\"scan\" type=\"button\">扫描附近 Wi-Fi</button></div><p class=\"hint\">扫描只显示 C6 支持的 2.4 GHz 网络。隐藏网络可以手动填写；双频同名网络需确保路由器启用了 2.4 GHz。</p><div id=\"scanStatus\" class=\"hint\" role=\"status\" aria-live=\"polite\">尚未扫描。</div><div id=\"networks\" class=\"network-list\" aria-label=\"可用的 2.4 GHz 网络\"></div></section>\n"
"<section class=\"card\"><h2>连接设置</h2><form id=\"wifiForm\" method=\"post\" action=\"/wifi\" autocomplete=\"off\"><div class=\"grid\"><label class=\"field wide\"><span>Wi-Fi 名称（SSID）</span><input id=\"ssid\" name=\"ssid\" type=\"text\" required autocomplete=\"off\" spellcheck=\"false\" placeholder=\"选择上方网络，或手动填写\" aria-describedby=\"networkLimit\"></label><label class=\"field wide\"><span>Wi-Fi 密码</span><input id=\"password\" name=\"password\" type=\"password\" autocomplete=\"new-password\" placeholder=\"开放网络可以留空\"><small>密码不会回显，发送后即清空，不保存到浏览器。</small></label></div><p id=\"networkLimit\" class=\"note\">仅支持 2.4 GHz；无法连接仅有 5 GHz 或 6 GHz 的 Wi-Fi。SSID 区分大小写，不需要修改电脑当前网络。</p><div class=\"actions\"><button id=\"connect\" class=\"primary\" type=\"submit\">保存并连接</button><button id=\"refresh\" type=\"button\">检查连接状态</button></div></form><div id=\"status\" class=\"status\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">填写网络名称和密码后，保存到这台 C6。</div></section>\n"
"<section class=\"card\"><h2>联网后的下一步</h2><p class=\"hint\">联网成功后设备屏幕显示局域网 IP，并自动关闭无密码配置热点。手机切回同一 Wi-Fi，再访问屏幕显示的地址；也可回到多屏灵犀的设备管理扫描添加 C6。实体、打印机与天气选择会自动同步到设备。</p><div class=\"actions\"><a href=\"/standalone\">配置独立运行卡片 →</a></div><details class=\"help\"><summary>无法连接时怎么办？</summary><p>先检查密码和路由器的 2.4 GHz 频段。如果未获取地址，可继续连接 Lingxi-C6 热点重试，或在 Mac 的 USB 刷机入口重新预配置 Wi-Fi。</p></details></section>\n"
"<footer class=\"footer\">XH Multiscreen · 通用 C6 测试固件<br>首次配置热点无需密码，联网成功后自动关闭。仅在可信环境使用。网络凭据由设备保存，网页不会读取或回显密码。</footer></main></div>\n"
"<script>\n"
"'use strict';\n"
"// Translate UI only. Device names, SSIDs, serials and task content stay intact.\n"
"let uiEnglish=typeof navigator!=='undefined'&&/^en\\b/i.test(navigator.language||'');\n"
"const uiStrings={\"通用监看屏\":\"General monitor\",\"显示内容\":\"Content\",\"屏幕预览\":\"Screen preview\",\"打印机\":\"Printers\",\"桌面时钟\":\"Desktop clock\",\"天气\":\"Weather\",\"设备\":\"Device\",\"屏幕与轮转\":\"Display & rotation\",\"自动休眠\":\"Auto sleep\",\"局域网连接\":\"LAN connection\",\"Wi-Fi 连接\":\"Wi-Fi setup\",\"设备设置\":\"Device settings\",\"网页外观\":\"Web appearance\",\"跟随系统\":\"System\",\"浅色\":\"Light\",\"深色\":\"Dark\",\"重试同步\":\"Retry sync\",\"网页与小屏使用同一语言，切换后自动保存。\":\"Web and display share one language. Changes save automatically.\",\"正在同步小屏语言…\":\"Syncing display language…\",\"网页与小屏语言已同步\":\"Web and display language synced\",\"网页已切换，小屏尚未同步，请重试\":\"Web language changed. Display not synced; retry.\",\"语言响应无效\":\"Invalid language response\",\"设备配置已变化，语言未同步。请重试；其他修改仍保留。\":\"Settings changed elsewhere. Language not synced; retry. Other edits are retained.\",\"设备地址\":\"Device address\",\"固件\":\"Firmware\",\"连接状态\":\"Connection status\",\"正在读取…\":\"Reading…\",\"设备屏幕实时画面\":\"Actual device display\",\" · 加入轮询\":\" · Include in rotation\",\"关闭\":\"Off\",\"尚未获取\":\"Not available yet\",\"可留空\":\"Optional\",\"XH Multiscreen · 通用 C6 测试固件\":\"XH Multiscreen · General C6 test firmware\",\"等待联网\":\"Waiting for network\",\"已连接\":\"Connected\",\"热点连接 · 等待联网\":\"Setup hotspot · waiting for network\",\"C6 测试固件\":\"C6 test firmware\",\"暂不可读取\":\"Unavailable\",\"将 C6 连接到你的局域网，随后在多屏灵犀中扫描添加。\":\"Connect C6 to your LAN, then discover it in Lingxi Multiscreen.\",\"仅支持 2.4 GHz\":\"2.4 GHz only\",\"选择网络\":\"Choose network\",\"扫描附近 Wi-Fi\":\"Scan nearby Wi-Fi\",\"扫描只显示 C6 支持的 2.4 GHz 网络。隐藏网络可以手动填写；双频同名网络需确保路由器启用了 2.4 GHz。\":\"Only supported 2.4 GHz networks appear. Enter hidden SSIDs manually. For dual-band names, enable the router’s 2.4 GHz band.\",\"尚未扫描。\":\"Not scanned yet.\",\"连接设置\":\"Connection settings\",\"Wi-Fi 名称（SSID）\":\"Wi-Fi name (SSID)\",\"Wi-Fi 密码\":\"Wi-Fi password\",\"密码不会回显，发送后即清空，不保存到浏览器。\":\"Passwords are not displayed or stored in the browser; they clear after sending.\",\"仅支持 2.4 GHz；无法连接仅有 5 GHz 或 6 GHz 的 Wi-Fi。SSID 区分大小写，不需要修改电脑当前网络。\":\"Only 2.4 GHz is supported, not 5 or 6 GHz. SSIDs are case-sensitive. Your computer’s network does not need to change.\",\"保存并连接\":\"Save & connect\",\"检查连接状态\":\"Check connection\",\"填写网络名称和密码后，保存到这台 C6。\":\"Enter the network name and password, then save to this C6.\",\"联网后的下一步\":\"After connecting\",\"配置独立运行卡片 →\":\"Configure local cards →\",\"无法连接时怎么办？\":\"Troubleshooting\",\"Wi-Fi 已连接\":\"Wi-Fi connected\",\"继续配置设备\":\"Continue setup\",\"手机切回同一 Wi-Fi，扫描小屏上的新二维码进入后台。\":\"Rejoin the same Wi-Fi and scan the new display QR to open settings.\",\"设备已连接局域网。现在可在多屏灵犀中扫描添加，或打开独立运行配置。\":\"Connected to LAN. Discover this C6 in the app or open local settings.\",\"尚未获取局域网地址\":\"No LAN address yet\",\"已连接局域网\":\"Connected to LAN\",\"暂不可读取 · 可重试\":\"Unavailable · retry\",\"请检查当前网络\":\"Check the current network\",\"正在扫描附近的 2.4 GHz 网络…\":\"Scanning nearby 2.4 GHz networks…\",\"已选择网络。填写密码后点击“保存并连接”。\":\"Network selected. Enter its password and choose Save & connect.\",\"信号强\":\"Strong signal\",\"信号良好\":\"Good signal\",\"信号较弱\":\"Weak signal\",\"开放 · \":\"Open · \",\"连接信息\":\"Connection information\",\"可用的 2.4 GHz 网络\":\"Available 2.4 GHz networks\",\"选择上方网络，或手动填写\":\"Choose a network above, or enter it manually\",\"开放网络可以留空\":\"Leave blank for an open network\",\"加入轮询\":\"Include in rotation\",\"网络信息保存在这台设备中。\":\"Network settings stay on this device.\",\"无需一直连接电脑，卡片仍可独立运行。\":\"Cards work without a connected computer.\",\"正在检查\":\"Checking…\",\"联网成功后设备屏幕显示局域网 IP，并自动关闭无密码配置热点。手机切回同一 Wi-Fi，再访问屏幕显示的地址；也可回到多屏灵犀的设备管理扫描添加 C6。实体、打印机与天气选择会自动同步到设备。\":\"Once connected, the display shows the LAN IP and the open hotspot closes. Rejoin the same Wi-Fi and open that address, or discover C6 in the app. Entity, printer and weather choices sync to the device.\",\"先检查密码和路由器的 2.4 GHz 频段。如果未获取地址，可继续连接 Lingxi-C6 热点重试，或在 Mac 的 USB 刷机入口重新预配置 Wi-Fi。\":\"Check your password and the router’s 2.4 GHz band. If no address appears, reconnect to the Lingxi-C6 hotspot or configure Wi-Fi through the Mac USB installer.\",\"首次配置热点无需密码，联网成功后自动关闭。仅在可信环境使用。网络凭据由设备保存，网页不会读取或回显密码。\":\"The first-setup hotspot is open and closes after connection. Use a trusted environment. Credentials stay on the device; the page never reads or displays saved passwords.\",\"连接超时，请检查设备网络后重试\":\"Connection timed out. Check the device network and retry.\",\"无法连接设备，请保持连接到 C6 热点或同一局域网\":\"Cannot connect. Stay on the C6 hotspot or the same LAN.\",\"请输入 1–32 个 UTF-8 字节的 SSID；中文名称按实际字节长度计算。\":\"SSID must be 1–32 UTF-8 bytes. Non-ASCII names use multiple bytes.\",\"密码可留空，或填写 8–63 个 UTF-8 字节；64 位密码须为十六进制 PSK。\":\"Leave the password blank, or enter 8–63 UTF-8 bytes. A 64-byte PSK must be hexadecimal.\",\"正在将网络设置保存到 C6…\":\"Saving network settings to C6…\",\"设备拒绝网络信息，请检查 SSID 与密码长度\":\"Device rejected network settings. Check SSID and password lengths.\",\"网络设置未保存，请稍后重试\":\"Network settings not saved. Retry later.\",\"网络设置已保存，正在等待设备获取局域网 IP。热点会自动关闭，请切回你的 Wi-Fi，按设备屏幕显示的局域网 IP 打开配置网页。\":\"Network settings saved. Waiting for a LAN IP. The hotspot closes automatically; rejoin your Wi-Fi and open the address shown on the display.\",\"设置已保存，但尚未确认联网。检查密码和 2.4 GHz 频段后重试；若热点已断开，请在软件中重新扫描。\":\"Saved, but connection is not confirmed. Check the password and 2.4 GHz band. If the hotspot has closed, scan again in the app.\",\"此固件暂不支持网页扫描。可手动填写 SSID，或在 Mac 的 USB 刷机入口扫描网络。\":\"This firmware cannot scan from the web. Enter the SSID manually or scan in the Mac USB installer.\",\"扫描未完成，请稍后重试或手动填写 SSID。\":\"Scan failed. Retry or enter the SSID manually.\",\"扫描超时，请稍后重试或手动填写 SSID。\":\"Scan timed out. Retry or enter the SSID manually.\",\"设备暂无法扫描，可能正在联网。请稍后重试，或手动填写 SSID。\":\"Device cannot scan while connecting. Retry later or enter the SSID manually.\",\"没有发现可用网络。请检查路由器 2.4 GHz 频段，或手动填写 SSID。\":\"No networks found. Check the 2.4 GHz band or enter the SSID manually.\"};\n"
"\n"
"function t(text){if(!uiEnglish)return text;if(uiStrings[text])return uiStrings[text];if(text.endsWith(' · 加入轮询'))return t(text.slice(0,-7))+' · Include in rotation';const match=text.match(/^请填写 (.+) 的数值$/);if(match)return'Enter a value for '+match[1];const range=text.match(/^请填写 (.+) 范围内的(整数|数值)$/);if(range)return'Enter '+(range[2]==='整数'?'a whole number':'a number')+' between '+range[1];return text;}\n"
"function printState(raw){const states={idle:['空闲','Idle'],printing:['打印中','Printing'],running:['打印中','Printing'],paused:['已暂停','Paused'],preprint:['准备中','Preparing'],postprint:['后处理中','Post-processing'],complete:['已完成','Complete'],completed:['已完成','Complete'],finished:['已完成','Complete'],offline:['离线','Offline'],error:['报错','Error'],cancelled:['已取消','Cancelled'],failed:['失败','Failed']};return states[String(raw||'').toLowerCase()]?.[uiEnglish?1:0]||raw||(uiEnglish?'Unknown':'未知');}\n"
"const staticText=new WeakMap();\n"
"const staticAttributes=new WeakMap();\n"
"function applyLanguage(){if(document.documentElement)document.documentElement.lang=uiEnglish?'en':'zh-CN';document.title='XH Multiscreen · C6';if(!document.createTreeWalker)return;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);while(walker.nextNode()){const node=walker.currentNode,parent=node.parentElement;if(!parent||parent.closest('script,style,[data-no-i18n],#printers,#entities,#themeColors,#rotationCards,#status,#deviceIP,#firmware,#connectionState,#configurationState,#draftState,#authState,#health,#networks,#scanStatus,#previewStatus,#previewCard,#languageStatus,#json'))continue;if(!staticText.has(node))staticText.set(node,node.nodeValue);const original=staticText.get(node),trimmed=original.trim();node.nodeValue=original.replace(trimmed,t(trimmed));}for(const element of document.querySelectorAll('[data-i18n]'))element.textContent=t(element.dataset.i18n);for(const element of document.querySelectorAll('[placeholder],[aria-label],[title]')){if(!staticAttributes.has(element))staticAttributes.set(element,Object.fromEntries(['placeholder','aria-label','title'].map(k=>[k,element.getAttribute(k)]).filter(([,v])=>v!==null)));for(const [key,value]of Object.entries(staticAttributes.get(element)))element.setAttribute(key,t(value));}const preview=document.getElementById('screenPreview');if(preview)preview.setAttribute('aria-label',t('设备屏幕实时画面'));}\n"
"function translatedText(element,text){element.dataset.i18n=text;element.textContent=t(text);}\n"
"function languageStatus(text,retry=false){document.getElementById('languageStatus').textContent=t(text);document.getElementById('languageStatus').dataset.state=retry?'error':'ready';document.getElementById('languageRetry').hidden=!retry;}\n"
"// Language is an isolated CAS write so unfinished forms never block this switch.\n"
"async function saveDeviceLanguage(wanted){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const info=await fetch('/api/info',{cache:'no-store',signal:controller.signal});if(!info.ok)throw Error(t('网页已切换，小屏尚未同步，请重试'));const before=await info.json();if(!Number.isInteger(before.revision)||before.revision<0)throw Error(t('语言响应无效'));const response=await fetch('/api/language',{method:'POST',cache:'no-store',signal:controller.signal,headers:{'Content-Type':'application/json','X-XH-Language':'1','X-Lingxi-LAN':'1'},body:JSON.stringify({revision:before.revision,language:wanted})});if(!response.ok){const e=Error(t(response.status===409?'设备配置已变化，语言未同步。请重试；其他修改仍保留。':'网页已切换，小屏尚未同步，请重试'));e.conflict=response.status===409;throw e;}const result=await response.json();if(!Number.isInteger(result.revision)||result.revision<before.revision||result.language!==wanted)throw Error(t('语言响应无效'));return{...result,previousRevision:before.revision};}finally{clearTimeout(timer);}}\n"
"function setupAppearance(){const select=document.getElementById('appearance');if(!select)return;select.onchange=()=>{if(select.value==='system')document.documentElement.removeAttribute('data-theme');else document.documentElement.setAttribute('data-theme',select.value);};}\n"
"\n"
"const el=id=>document.getElementById(id),bytes=value=>new TextEncoder().encode(value).length;let connecting=false,scanning=false,scanTimer=null,connectionTimer=null,alive=true,languageChosen=false,languageBusy=false,infoSnapshot=null,messageSource='填写网络名称和密码后，保存到这台 C6。';\n"
"const setupLinks=new Map(Array.from(document.querySelectorAll('a[href^=\"/standalone\"]'),link=>[link,link.getAttribute('href')]));\n"
"function message(text,tone=''){messageSource=text;el('status').textContent=t(text);el('status').dataset.tone=tone;}\n"
"async function request(url,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{return await fetch(url,{cache:'no-store',...options,signal:controller.signal});}catch(e){throw Error(e.name==='AbortError'?'连接超时，请检查设备网络后重试':'无法连接设备，请保持连接到 C6 热点或同一局域网');}finally{clearTimeout(timer);}}\n"
"function setBusy(value){connecting=value;el('pageLanguage').disabled=value||languageBusy;el('languageRetry').disabled=value||languageBusy;el('connect').disabled=value||languageBusy;el('ssid').disabled=value||languageBusy;el('password').disabled=value||languageBusy;el('scan').disabled=value||scanning||languageBusy;for(const button of el('networks').querySelectorAll('button'))button.disabled=value||languageBusy;}\n"
"async function refreshInfo(){try{const r=await request('/api/info');if(!r.ok)throw Error('状态不可读取');const info=await r.json();if(!alive)return false;infoSnapshot=info;if(!languageChosen){uiEnglish=info.language===1;el('pageLanguage').value=uiEnglish?1:0;applyLanguage();message(messageSource);}const online=info.wifi_connected!==false&&privateIP(info.ip);if(online){for(const [link,path] of setupLinks)link.href='http://'+info.ip+path;el('lanAddress').textContent='http://'+info.ip+'/standalone';el('handoff').hidden=false;}else el('handoff').hidden=true;el('deviceIP').textContent=online?info.ip:t('热点连接 · 等待联网');el('firmware').textContent=info.fw||t('C6 测试固件');el('connectionState').textContent=t(online?'已连接局域网':'尚未获取局域网地址');return !!online;}catch{if(alive){el('connectionState').textContent=t('暂不可读取 · 可重试');el('deviceIP').textContent=t('请检查当前网络');}return false;}}\n"
"async function connect(event){event?.preventDefault();if(connecting||languageBusy)return;const ssid=el('ssid').value,password=el('password').value;if(!bytes(ssid)||bytes(ssid)>32||ssid.includes('\\0')){message('请输入 1–32 个 UTF-8 字节的 SSID；中文名称按实际字节长度计算。','error');el('ssid').focus();return;}if(password.includes('\\0')||!(password.length===0||(bytes(password)>=8&&bytes(password)<=63)||(bytes(password)===64&&/^[0-9a-f]{64}$/i.test(password)))){message('密码可留空，或填写 8–63 个 UTF-8 字节；64 位密码须为十六进制 PSK。','error');el('password').focus();return;}setBusy(true);message('正在将网络设置保存到 C6…');try{const r=await request('/wifi',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-XH-WiFi':'1'},body:new URLSearchParams({ssid,password}).toString()});if(!r.ok)throw Error(r.status===400?'设备拒绝网络信息，请检查 SSID 与密码长度':'网络设置未保存，请稍后重试');el('password').value='';message('网络设置已保存，正在等待设备获取局域网 IP。热点会自动关闭，请切回你的 Wi-Fi，按设备屏幕显示的局域网 IP 打开配置网页。','success');let remaining=20;const poll=async()=>{if(!alive)return;if(await refreshInfo()){message('设备已连接局域网。现在可在多屏灵犀中扫描添加，或打开独立运行配置。','success');return;}if(--remaining>0)connectionTimer=setTimeout(poll,3000);else message('设置已保存，但尚未确认联网。检查密码和 2.4 GHz 频段后重试；若热点已断开，请在软件中重新扫描。');};if(connectionTimer)clearTimeout(connectionTimer);connectionTimer=setTimeout(poll,3000);}catch(e){message(e.message,'error');}finally{setBusy(false);}}\n"
"function showNetworks(networks){el('networks').replaceChildren();for(const network of networks){if(typeof network.ssid!=='string'||!network.ssid)continue;const button=document.createElement('button');button.type='button';const name=document.createElement('span');name.textContent=network.ssid;const signal=document.createElement('small');signal.textContent=(network.open?t('开放 · '):'')+t(network.rssi>=-55?'信号强':network.rssi>=-75?'信号良好':'信号较弱');button.append(name,signal);button.onclick=()=>{if(el('ssid').value!==network.ssid)el('password').value='';el('ssid').value=network.ssid;for(const item of el('networks').querySelectorAll('button'))item.removeAttribute('aria-pressed');button.setAttribute('aria-pressed','true');el('password').focus();message('已选择网络。填写密码后点击“保存并连接”。');};el('networks').append(button);}}\n"
"async function scan(){if(scanning||connecting||languageBusy)return;scanning=true;el('scan').disabled=true;el('scanStatus').textContent=t('正在扫描附近的 2.4 GHz 网络…');let remaining=20;const poll=async start=>{try{const r=await request('/api/wifi/scan'+(start?'?start=1':''));if(!r.ok)throw Error(r.status===404?'此固件暂不支持网页扫描。可手动填写 SSID，或在 Mac 的 USB 刷机入口扫描网络。':'扫描未完成，请稍后重试或手动填写 SSID。');const result=await r.json();if(!alive)return;if(result.busy){if(--remaining<=0)throw Error('扫描超时，请稍后重试或手动填写 SSID。');scanTimer=setTimeout(()=>poll(false),500);return;}if(result.error)throw Error(result.message||'设备暂无法扫描，可能正在联网。请稍后重试，或手动填写 SSID。');showNetworks(result.networks||[]);el('scanStatus').textContent=result.networks?.length?(uiEnglish?'Found '+result.networks.length+' networks. Choose one or enter a hidden SSID.':'找到 '+result.networks.length+' 个网络；选择一个，或手动填写隐藏网络。'):t('没有发现可用网络。请检查路由器 2.4 GHz 频段，或手动填写 SSID。');}catch(e){el('scanStatus').textContent=t(e.message);}scanning=false;el('scan').disabled=connecting;};await poll(true);}\n"
"el('wifiForm').onsubmit=connect;el('scan').onclick=scan;el('refresh').onclick=refreshInfo;el('ssid').oninput=()=>{el('password').value='';};window.addEventListener('pagehide',()=>{alive=false;el('password').value='';clearTimeout(scanTimer);clearTimeout(connectionTimer);});function privateIP(value){const p=String(value||'').split('.');if(p.length!==4||p.some(n=>!/^\\d{1,3}$/.test(n)||Number(n)>255))return false;const [a,b]=p.map(Number);return a===10||(a===192&&b===168)||(a===172&&b>=16&&b<=31);}\n"
"async function switchLanguage(){if(connecting||scanning||languageBusy)return;languageChosen=true;uiEnglish=el('pageLanguage').value==='1';applyLanguage();message(messageSource);languageBusy=true;setBusy(false);languageStatus('正在同步小屏语言…');try{const result=await saveDeviceLanguage(uiEnglish?1:0);if(!alive)return;if(infoSnapshot)Object.assign(infoSnapshot,{language:result.language,revision:result.revision});languageStatus('网页与小屏语言已同步');}catch(e){if(alive)languageStatus(e.message,true);}finally{languageBusy=false;if(alive)setBusy(false);}}\n"
"el('pageLanguage').onchange=switchLanguage;el('languageRetry').onclick=switchLanguage;setupAppearance();applyLanguage();el('pageLanguage').value=uiEnglish?1:0;languageStatus('网页与小屏使用同一语言，切换后自动保存。');refreshInfo();\n"
"</script></body></html>\n"
"\n";
#endif
